import{_ as i,c as s,o as t,a3 as a}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"Permissions macOS","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/permissions.md","filePath":"fr/guide/permissions.md","lastUpdated":1787284674000}'),r={name:"fr/guide/permissions.md"};function o(n,e,l,u,c,p){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="permissions-macos" tabindex="-1">Permissions macOS <a class="header-anchor" href="#permissions-macos" aria-label="Permalink to &quot;Permissions macOS&quot;">​</a></h1><p>ClipboxAI peut demander quelques permissions macOS pour offrir la meilleure expérience. Cette page explique à quoi sert chaque permission et comment la gérer.</p><h2 id="presse-papiers-automation" tabindex="-1">Presse-papiers / Automation <a class="header-anchor" href="#presse-papiers-automation" aria-label="Permalink to &quot;Presse-papiers / Automation&quot;">​</a></h2><p>Pour capturer votre presse-papiers en arrière-plan et renvoyer les résultats, ClipboxAI utilise l&#39;accès Automation de macOS.</p><p><strong>À quoi il sert</strong> : lire le presse-papiers actuel lorsque vous copiez, et écrire les résultats en retour lorsque vous exécutez une action.</p><p><strong>Gérer</strong> : <strong>Réglages système → Confidentialité et sécurité → Automation</strong> → activez <strong>ClipboxAI</strong>.</p><p>Accordez l&#39;accès lorsque vous y êtes invité lors du premier lancement. Vous pouvez le gérer ou le révoquer à tout moment.</p><h2 id="accessibilite-facultatif" tabindex="-1">Accessibilité (facultatif) <a class="header-anchor" href="#accessibilite-facultatif" aria-label="Permalink to &quot;Accessibilité (facultatif)&quot;">​</a></h2><p>Certaines versions utilisent l&#39;Accessibilité pour fournir des raccourcis clavier globaux et activer le panneau d&#39;historique depuis n&#39;importe où.</p><p><strong>À quoi il sert</strong> : ouvrir le panneau d&#39;historique et exécuter des actions via des raccourcis, même lorsque l&#39;application n&#39;a pas le focus.</p><p><strong>Gérer</strong> : <strong>Réglages système → Confidentialité et sécurité → Accessibilité</strong> → activez <strong>ClipboxAI</strong>.</p><h2 id="notifications-facultatif" tabindex="-1">Notifications (facultatif) <a class="header-anchor" href="#notifications-facultatif" aria-label="Permalink to &quot;Notifications (facultatif)&quot;">​</a></h2><p>ClipboxAI peut afficher des notifications lorsqu&#39;une action de longue durée se termine ou nécessite votre attention.</p><p><strong>À quoi il sert</strong> : vous alerter lorsqu&#39;une action se termine ou lorsqu&#39;une configuration est requise.</p><p><strong>Gérer</strong> : <strong>Réglages système → Notifications</strong> → <strong>ClipboxAI</strong>.</p><h2 id="acces-au-disque-complet-facultatif" tabindex="-1">Accès au disque complet (facultatif) <a class="header-anchor" href="#acces-au-disque-complet-facultatif" aria-label="Permalink to &quot;Accès au disque complet (facultatif)&quot;">​</a></h2><p>Non requis pour une utilisation normale. Nécessaire uniquement si vous souhaitez que l&#39;application lise des éléments depuis des emplacements protégés par le système.</p><p><strong>Gérer</strong> : <strong>Réglages système → Confidentialité et sécurité → Accès au disque complet</strong>.</p><p>Cette permission est facultative et n&#39;est nécessaire que dans des scénarios avancés.</p><h2 id="reinitialiser-une-permission-avec-le-terminal" tabindex="-1">Réinitialiser une permission avec le Terminal <a class="header-anchor" href="#reinitialiser-une-permission-avec-le-terminal" aria-label="Permalink to &quot;Réinitialiser une permission avec le Terminal&quot;">​</a></h2><p>Si une fenêtre de permission a été ignorée ou que l&#39;état est incohérent, vous pouvez réinitialiser les invites de permission macOS à l&#39;aide de <code>tccutil</code> :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Réinitialiser les invites d&#39;automation/accessibilité pour ClipboxAI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p>Après l&#39;exécution de <code>tccutil</code>, redémarrez l&#39;application et déclenchez à nouveau la fonctionnalité pour être invité de nouveau.</p><h2 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h2><ul><li>Si l&#39;historique du presse-papiers ne capture pas les copies, vérifiez que la permission <strong>Automation</strong> est accordée.</li><li>Si les raccourcis globaux ne fonctionnent pas, vérifiez la permission <strong>Accessibilité</strong>.</li><li>Après toute modification des permissions, quittez et rouvrez toujours ClipboxAI pour que les changements prennent effet.</li></ul><p>Pour plus d&#39;aide, consultez le <a href="/fr/guide/troubleshooting.html">guide de dépannage</a>.</p>`,26)])])}const g=i(r,[["render",o]]);export{m as __pageData,g as default};
